
/* Clicash — application installable, stockage local de démonstration. */
const SafeStorage=(()=>{
  const memory=new Map();let native=null;
  try{native=window.localStorage;const probe='__clicash_storage_probe__';native.setItem(probe,'1');native.removeItem(probe);}catch(e){native=null;}
  return {
    getItem(key){try{const value=native&&native.getItem(key);if(value!==null&&value!==undefined){memory.set(key,value);return value;}}catch(e){}return memory.has(key)?memory.get(key):null;},
    setItem(key,value){value=String(value);memory.set(key,value);try{if(native)native.setItem(key,value);}catch(e){}},
    removeItem(key){memory.delete(key);try{if(native)native.removeItem(key);}catch(e){}}
  };
})();

