const Store={
  key:'monempire.db.v1',cache:null,
  read(){
    if(this.cache)return this.cache;
    const raw=SafeStorage.getItem(this.key);
    if(raw){let parsed=null;try{parsed=JSON.parse(raw);}catch(e){}
      if(parsed){this.cache=parsed;this.migrate();return this.cache;}}
    this.cache=this.seed();this.write();return this.cache;
  },
  migrate(){
    const db=this.cache;let changed=false;
    const arrays=['users','wallets','wallet_transactions','referrals','referral_progress','referral_relations','withdrawal_requests','unlock_payments','withdraw_objectives','notifications','support_requests','user_settings','security_logs','market_inventory','market_resales','market_shipments','market_deposits'];
    arrays.forEach(k=>{if(!Array.isArray(db[k])){db[k]=[];changed=true;}});
    if(!Array.isArray(db.market_products)){db.market_products=MARKET_PRODUCTS.map(x=>({...x}));changed=true;}
    if(!db.app_settings||typeof db.app_settings!=='object'||Array.isArray(db.app_settings)){db.app_settings={};changed=true;}
    ['games','game_sessions','clicker_states'].forEach(k=>{if(k in db){delete db[k];changed=true;}});
    if(db.users.some(x=>x.isSeed)){db.users=db.users.filter(x=>!x.isSeed);db.wallets=db.wallets.filter(x=>db.users.some(u=>u.id===x.userId));changed=true;}
    const before=db.withdraw_objectives.length;
    db.withdraw_objectives=db.withdraw_objectives.filter(x=>!['games_played','challenges_done','clicker_points','clicks_total'].includes(x.type));
    if(before!==db.withdraw_objectives.length)changed=true;
    if(changed)this.write();
  },
  write(){SafeStorage.setItem(this.key,JSON.stringify(this.cache));if(typeof updateTopBalance==='function')updateTopBalance();},
  mutate(fn){const db=this.read();const r=fn(db);this.write();return r;},
  seed(){
    const now=new Date().toISOString();
    return {meta:{version:2,createdAt:now,backend:'stockage local — démonstration, sans serveur'},users:[],wallets:[],wallet_transactions:[],referrals:[],referral_progress:[],referral_relations:[],withdrawal_requests:[],unlock_payments:[],withdraw_objectives:[],app_settings:{},market_products:MARKET_PRODUCTS.map(x=>({...x})),market_inventory:[],market_resales:[],market_shipments:[],market_deposits:[],notifications:[],support_requests:[],user_settings:[],security_logs:[]};
  }
};

