function topBalText(u){ if(SafeStorage.getItem('me_hide')==='1') return '•••'; const w=Store.read().wallets.find(x=>x.userId===u.id); return ckFmt(w?w.balance:0); }
function updateTopBalance(){ try{ const e=document.getElementById('tbBal'); if(!e) return; const u=Auth.currentUser(); if(!u) return; const t=topBalText(u); if(e.textContent!==t) e.textContent=t; }catch(_){} }
/* ---------- PWA : installation + hors ligne ---------- */
const PWA={ prompt:null,
  standalone(){ return (window.matchMedia&&matchMedia('(display-mode: standalone)').matches)||navigator.standalone===true; },
  ios(){ return /iphone|ipad|ipod/i.test(navigator.userAgent)&&!window.MSStream; },
  async install(){ if(!this.prompt) return false; this.prompt.prompt(); let r=null; try{ r=await this.prompt.userChoice; }catch(_){} this.prompt=null; updateInstallUI(); return !!(r&&r.outcome==='accepted'); },
  dismissed(){ try{ return SafeStorage.getItem('clicash.pwa.dismiss')==='1'; }catch(_){ return false; } } };
function pwaCardHTML(slot){ const banner=slot==='banner';
  if(PWA.standalone()) return banner?'':'<div class="card pwa-card ok"><div class="pwa-ico">'+logoImg()+'</div><div class="pwa-txt"><h4>Application installée</h4><p>Clicash est installée sur cet appareil : plein écran et lancement rapide.</p></div><span class="badge b-green">'+ic('check')+'Installée</span></div>';
  const can=!!PWA.prompt, ios=PWA.ios();
  if(banner&&(!(can||ios)||PWA.dismissed())) return '';
  const hint=can?'Ajoute Clicash à ton écran d\u2019accueil : lancement plein écran, accès rapide et utilisation hors ligne.'
    :(ios?'Sur iPhone : touche <b>Partager</b> '+ic('share-2')+' puis <b>Sur l\u2019écran d\u2019accueil</b>.'
    :'Dans le menu de ton navigateur, choisis <b>Installer l\u2019application</b> ou <b>Ajouter à l\u2019écran d\u2019accueil</b>.');
  return '<div class="card pwa-card"><div class="pwa-ico">'+logoImg()+'</div><div class="pwa-txt"><h4>Installer Clicash</h4><p>'+hint+'</p></div>'
    +(can?'<button class="btn btn-primary btn-sm" onclick="PWA.install()">'+ic('download')+'Installer</button>':'')
    +(banner?'<button class="icon-btn pwa-x" onclick="pwaDismiss()" aria-label="Fermer">'+ic('x')+'</button>':'')+'</div>'; }
function pwaDismiss(){ try{ SafeStorage.setItem('clicash.pwa.dismiss','1'); }catch(_){} updateInstallUI(); }
function updateInstallUI(){ const a=document.getElementById('pwaSlot'), b=document.getElementById('pwaCard');
  if(a) a.innerHTML=pwaCardHTML('banner'); if(b) b.innerHTML=pwaCardHTML('card'); if((a||b)&&window.lucide) lucide.createIcons(); }
window.addEventListener('beforeinstallprompt',e=>{ e.preventDefault(); PWA.prompt=e; updateInstallUI(); });
window.addEventListener('appinstalled',()=>{ PWA.prompt=null; try{ toast('Clicash est installée','ok','check-circle-2'); }catch(_){} updateInstallUI(); });
window.addEventListener('offline',()=>{ try{ toast('Hors ligne : tes données restent sur cet appareil','warn','wifi-off'); }catch(_){} });
window.addEventListener('online',()=>{ try{ toast('Connexion rétablie','ok','wifi'); }catch(_){} });
if('serviceWorker' in navigator&&(location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1')){
  window.addEventListener('load',()=>{ navigator.serviceWorker.register('sw.js').catch(()=>{}); }); }

/* ================= 3. SERVICES ================= */
async function hashPwd(pwd,salt){ const d=new TextEncoder().encode(salt+'::'+pwd); const b=await crypto.subtle.digest('SHA-256',d); return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join(''); }
function logSecurity(userId,event,details){ Store.mutate(db=>db.security_logs.unshift({id:uid(),userId,event,details:details||'',date:new Date().toISOString()})); }

const Session={ key:'monempire.session',
  set(userId){ SafeStorage.setItem(this.key, JSON.stringify({userId, token:genCode(24), exp:Date.now()+7*864e5})); },
  current(){ try{ const s=JSON.parse(SafeStorage.getItem(this.key)); if(!s) return null; if(Date.now()>s.exp){ this.clear(); return {expired:true}; } return s; }catch(e){ return null; } },
  clear(){ SafeStorage.removeItem(this.key); } };

const Auth={
  currentUser(){ const s=Session.current(); if(!s||s.expired) return null;
    const db=Store.read(); const u=db.users.find(x=>x.id===s.userId&&!x.isSeed);
    if(!u){ Session.clear(); return null; }
    return {...u, settings: db.user_settings.find(x=>x.userId===u.id)||{}}; },
  async signup(d){
    const db=Store.read();
    if(db.users.some(u=>u.email.toLowerCase()===d.email.toLowerCase()&&!u.isSeed)) throw new Error('Un compte existe déjà avec cette adresse e-mail.');
    if(db.users.some(u=>u.pseudo.toLowerCase()===d.pseudo.toLowerCase())) throw new Error('Ce pseudo est déjà pris.');
    const salt=genCode(12), pass=await hashPwd(d.password,salt), now=new Date().toISOString(), id='u-'+uid();
    Store.mutate(db=>{
      db.users.push({id, nom:d.nom, prenom:d.prenom, pseudo:d.pseudo, email:d.email, phone:d.phone, pass, salt, emailVerified:false, avatar:null, devices:[Device.id()], createdAt:now});
      db.wallets.push({userId:id, balance:0, pending:0, totalEarned:0, accountNo:'ME26-'+Math.floor(100000+Math.random()*900000), status:'actif', createdAt:now});
      db.referrals.push({userId:id, code:Referral.newCode(db), invited:0, confirmed:0, verified:0, createdAt:now});
      db.user_settings.push({userId:id, notifEmail:true, notifPush:true, language:'fr', display:'confort', privacyLeaderboard:true});
    });
    logSecurity(id,'inscription','Compte créé');
    Auth.lastReferral=Referral.applyPending(id);
    Session.set(id);
    Notif.add(id,{title:'Bienvenue sur Clicash', msg:'Ton espace marketplace est prêt. Explore le catalogue et consulte ton portefeuille CLI.', cat:'systeme'});
    return id;
  },
  async login(ident,pwd){
    const db=Store.read(); const now=Date.now();
    const fails=db.security_logs.filter(l=>l.event==='echec_connexion'&&now-new Date(l.date)<5*60000);
    if(fails.length>=5) throw new Error('Trop de tentatives. Réessaie dans 5 minutes.');
    const u=db.users.find(x=>!x.isSeed&&(x.email.toLowerCase()===ident.toLowerCase()||x.pseudo.toLowerCase()===ident.toLowerCase()));
    if(!u){ logSecurity(null,'echec_connexion',ident); throw new Error('Identifiants incorrects.'); }
    const h=await hashPwd(pwd,u.salt);
    if(h!==u.pass){ logSecurity(u.id,'echec_connexion','Mot de passe erroné'); throw new Error('Identifiants incorrects.'); }
    Session.set(u.id); logSecurity(u.id,'connexion','Session ouverte'); touchDevice(u.id); Referral.reconcile(u.id);
    return u;
  },
  logout(){ const u=Auth.currentUser(); if(u) logSecurity(u.id,'deconnexion','Session fermée'); Session.clear(); },
  requestCode(userId){ const code=genCode(6); Store.mutate(db=>{ const u=db.users.find(x=>x.id===userId); u.pendingCode=code; u.codeExp=Date.now()+10*60000; }); return code; },
  verifyEmail(userId,code){ return Store.mutate(db=>{ const u=db.users.find(x=>x.id===userId);
    if(!u.pendingCode||u.pendingCode!==code||Date.now()>(u.codeExp||0)) return false;
    u.emailVerified=true; delete u.pendingCode; delete u.codeExp; return true; }); },
  async changePassword(userId,oldP,newP){
    const u=Store.read().users.find(x=>x.id===userId);
    if(await hashPwd(oldP,u.salt)!==u.pass) throw new Error('Mot de passe actuel incorrect.');
    const salt=genCode(12); const pass=await hashPwd(newP,salt);
    Store.mutate(db=>{ const uu=db.users.find(x=>x.id===userId); uu.pass=pass; uu.salt=salt; });
    logSecurity(userId,'changement_mdp','Mot de passe modifié');
  },
  findForReset(email){ const u=Store.read().users.find(x=>!x.isSeed&&x.email.toLowerCase()===email.toLowerCase());
    if(!u) throw new Error('Aucun compte ne correspond à cette adresse.');
    const code=genCode(6); Store.mutate(db=>{ const uu=db.users.find(x=>x.id===u.id); uu.pendingCode=code; uu.codeExp=Date.now()+10*60000; });
    return {userId:u.id, code}; },
  async resetPassword(userId,code,newP){
    const ok=Store.mutate(db=>{ const u=db.users.find(x=>x.id===userId);
      if(!u.pendingCode||u.pendingCode!==code||Date.now()>(u.codeExp||0)) return false;
      delete u.pendingCode; delete u.codeExp; return true; });
    if(!ok) throw new Error('Code invalide ou expiré.');
    const salt=genCode(12), pass=await hashPwd(newP,salt);
    Store.mutate(db=>{ const u=db.users.find(x=>x.id===userId); u.pass=pass; u.salt=salt; });
    logSecurity(userId,'reinitialisation_mdp','Mot de passe réinitialisé');
  }
};

const Wallet={
  get(userId){ let w=Store.read().wallets.find(x=>x.userId===userId);
    if(!w) Store.mutate(db=>{ w={userId, balance:0, pending:0, totalEarned:0, accountNo:'ME26-'+Math.floor(100000+Math.random()*900000), status:'actif', createdAt:new Date().toISOString()}; db.wallets.push(w); });
    return w; },
  txs(userId){ return Store.read().wallet_transactions.filter(t=>t.userId===userId); },
  credit(userId,amount,opts){ opts=opts||{};
    Store.mutate(db=>{ const w=db.wallets.find(x=>x.userId===userId);
      const tx={id:uid(), userId, type:opts.type||'credit', label:opts.label||'Crédit', amount, status:opts.status||'confirmé', ref:'TX-'+genCode(7), meta:opts.meta||{}, date:new Date().toISOString()};
      db.wallet_transactions.unshift(tx);
      if(tx.status==='confirmé'){ w.balance+=amount; w.totalEarned+=amount; }
      else if(tx.status==='en attente'){ w.pending+=amount; } }); },
  weekEarnings(userId){ const days=[]; for(let i=6;i>=0;i--){ const d=new Date(); d.setDate(d.getDate()-i);
      const total=Store.read().wallet_transactions.filter(t=>t.userId===userId&&t.status==='confirmé'&&t.amount>0&&new Date(t.date).toDateString()===d.toDateString()).reduce((s,t)=>s+t.amount,0);
      days.push({label:d.toLocaleDateString('fr-FR',{weekday:'short'}), total}); } return days; }
};

const MARKET_TRANSPORTS=[
  {id:'air',name:'Avion',price:12000,extra:1800,daysMin:3,daysMax:7},
  {id:'train',name:'Train',price:7000,extra:1200,daysMin:7,daysMax:14},
  {id:'road',name:'Voiture ou camion',price:5000,extra:900,daysMin:10,daysMax:21},
  {id:'boat',name:'Bateau',price:3500,extra:1400,daysMin:25,daysMax:45},
  {id:'digital',name:'Livraison numérique',price:0,extra:0,daysMin:0,daysMax:0}
];
const Market={
  today(){return Math.floor(Date.now()/86400000);},
  product(id){return Store.read().market_products.find(x=>x.id===id)||null;},
  quoteAt(p,day){
    const seed=Array.from(p.id).reduce((n,c)=>(n*31+c.charCodeAt(0))%997,17);
    const start=Math.floor(Date.UTC(2026,0,1)/86400000);
    let value=p.price;
    for(let d=start;d<=day;d++){
      const wave=Math.sin((d+seed)*.19)*Math.min(.12,(Number(p.trendSeed)||4)/100)+Math.sin((d+seed*.7)*.071)*.045;
      const target=p.price*(1+wave+Math.sin((d+seed)*.012)*.035);
      const low=Math.max(p.price*MARKET_RULES.minFactor,value*(1-MARKET_RULES.dailyCap));
      const high=Math.min(p.price*MARKET_RULES.maxFactor,value*(1+MARKET_RULES.dailyCap));
      value=Math.max(low,Math.min(high,target));
    }
    return Math.max(1,Math.round(value));
  },
  quote(p){return this.quoteAt(p,this.today());},
  history(p,count){
    count=count||14;const out=[];
    for(let i=count-1;i>=0;i--)out.push(this.quoteAt(p,this.today()-i));
    return out;
  },
  trend(p){const a=this.quoteAt(p,this.today()-1),b=this.quote(p),delta=(b-a)/a;
    return Math.abs(delta)<.003?{name:'Stable',icon:'minus',className:'b-gray',delta:0}:{name:delta>0?'En hausse':'En baisse',icon:delta>0?'trending-up':'trending-down',className:delta>0?'b-green':'b-red',delta};},
  inventory(userId){return Store.read().market_inventory.filter(x=>x.ownerId===userId);},
  resales(userId){return Store.read().market_resales.filter(x=>x.userId===userId);},
  shipments(userId){return Store.read().market_shipments.filter(x=>x.userId===userId);},
  currentValue(item,day){const p=this.product(item.productId);return p?this.quoteAt(p,day===undefined?this.today():day):item.purchasePrice;},
  transport(id){return MARKET_TRANSPORTS.find(x=>x.id===id)||MARKET_TRANSPORTS[2];},
  buy(userId,productId,transportId,destination){
    const transport=this.transport(transportId), now=new Date(), date=now.toISOString();
    return Store.mutate(db=>{
      const p=db.market_products.find(x=>x.id===productId), w=db.wallets.find(x=>x.userId===userId);
      if(!p||p.stock<1)return {ok:false,err:'Ce produit n’est plus disponible.'};
      if(!w)return {ok:false,err:'Portefeuille introuvable.'};
      if(p.category==='Produits numériques'&&transportId!=='digital')return {ok:false,err:'Choisis la livraison numérique pour ce produit.'};
      if(p.category!=='Produits numériques'&&transportId==='digital')return {ok:false,err:'Ce produit nécessite un transport physique.'};
      const price=p.price,total=price+transport.price+transport.extra;
      if(w.balance<total)return {ok:false,err:'Solde insuffisant. Il te manque '+fmt(total-w.balance)+' CLI.'};
      const arrival=new Date(now.getTime()+(transport.daysMin+transport.daysMax)*43200000).toISOString();
      const itemId='INV-'+uid(),shipmentId='SHP-'+uid(),ref='TX-'+genCode(7),tracking='CL-'+genCode(9);
      w.balance-=total;p.stock-=1;
      const shipment={id:shipmentId,itemId,userId,productId,transportId,destination:destination.trim(),origin:'Lomé, Togo',tracking,price:transport.price,extra:transport.extra,createdAt:date,estimatedArrivalAt:arrival,status:'Transporteur à connecter'};
      const item={id:itemId,ownerId:userId,productId,purchasePrice:price,deliveryPrice:transport.price+transport.extra,purchasedAt:date,status:'En attente de livraison',shipmentId};
      db.market_inventory.unshift(item);db.market_shipments.unshift(shipment);
      db.wallet_transactions.unshift({id:uid(),userId,type:'achat',label:'Achat marketplace · '+p.name,amount:price,status:'confirmé',ref,date,meta:{productId,itemId}});
      if(transport.price+transport.extra)db.wallet_transactions.unshift({id:uid(),userId,type:'livraison',label:'Transport · '+p.name,amount:transport.price+transport.extra,status:'confirmé',ref:'TX-'+genCode(7),date,meta:{shipmentId,transportId}});
      return {ok:true,item,shipment,total};
    });
  },
  requestResale(userId,itemId){
    const date=new Date(),now=date.toISOString();
    return Store.mutate(db=>{
      const item=db.market_inventory.find(x=>x.id===itemId&&x.ownerId===userId);
      if(!item)return {ok:false,err:'Produit introuvable dans ton inventaire.'};
      if(db.market_resales.some(x=>x.itemId===itemId&&['Demande enregistrée','En attente de traitement'].includes(x.status)))return {ok:false,err:'Une demande de revente est déjà en cours.'};
      const p=db.market_products.find(x=>x.id===item.productId);if(!p)return {ok:false,err:'Produit indisponible.'};
      const gross=this.quote(p),fee=Math.ceil(gross*MARKET_RULES.resaleFee),endsAt=new Date(date.getTime()+7*86400000).toISOString();
      const resale={id:'RSL-'+uid(),itemId,userId,productId:item.productId,purchasePrice:item.purchasePrice,currentValue:gross,fee,net:gross-fee,createdAt:now,estimatedAt:endsAt,status:'En attente de traitement',tracking:'RS-'+genCode(8)};
      db.market_resales.unshift(resale);item.resalePreviousStatus=item.status;item.status='Revente demandée';
      return {ok:true,resale};
    });
  },
  cancelResale(userId,resaleId){
    return Store.mutate(db=>{
      const r=db.market_resales.find(x=>x.id===resaleId&&x.userId===userId&&x.status==='En attente de traitement');
      if(!r)return {ok:false,err:'Cette demande ne peut plus être annulée.'};
      r.status='Annulée';r.cancelledAt=new Date().toISOString();
      const item=db.market_inventory.find(x=>x.id===r.itemId);if(item){item.status=item.resalePreviousStatus||'En attente de livraison';delete item.resalePreviousStatus;}
      return {ok:true};
    });
  },
  requestDeposit(userId,amount,method){
    amount=Number(amount);
    if(!Number.isInteger(amount)||amount<1000||amount%100!==0)return {ok:false,err:'Saisis un montant d’au moins 1 000 F CFA, par tranches de 100.'};
    const row={id:'DEP-'+uid(),userId,amount,cli:amount,fee:0,method,status:'Prestataire non connecté',createdAt:new Date().toISOString(),reference:'DP-'+genCode(8)};
    Store.mutate(db=>db.market_deposits.unshift(row));return {ok:true,row};
  }
};
function marketChart(values,large){
  const w=large?520:150,h=large?112:44,pad=4,min=Math.min(...values),max=Math.max(...values),span=max-min||1;
  const pts=values.map((v,i)=>(pad+i*(w-2*pad)/(values.length-1))+','+(h-pad-(v-min)*(h-2*pad)/span)).join(' ');
  return '<svg class="market-spark'+(large?' large':'')+'" viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none" aria-label="Historique indicatif des prix"><polyline points="'+pts+'"/></svg>';
}
function marketFormatDelta(p){const t=Market.trend(p);return (t.delta>0?'+':'')+(t.delta*100).toFixed(1).replace('.',',')+' %';}
function deliveryCard(item){
  const sh=Store.read().market_shipments.find(x=>x.id===item.shipmentId),p=Market.product(item.productId);
  if(!sh||!p)return '';
  const transport=Market.transport(sh.transportId),digital=sh.transportId==='digital';
  return '<article class="card delivery-card"><div class="delivery-head"><div class="product-thumb"><img src="'+esc(p.image)+'" alt="'+esc(p.name)+'"></div><div class="delivery-product"><b>'+esc(p.name)+'</b><span>Suivi '+esc(sh.tracking)+'</span>'+badgeStatus(sh.status)+'</div><span class="badge b-blue">'+ic(digital?'download':'map')+(digital?'Numérique':transport.name)+'</span></div>'
    +'<div class="route-map"><div class="route-title">'+ic('route')+'Itinéraire indicatif</div><div class="route-line"><span class="route-point done"></span><span class="route-point"></span><span class="route-point"></span><span class="route-point"></span></div><div class="route-stops"><span>'+esc(digital?'Commande':sh.origin)+'</span><span>Collecte</span><span>Transit</span><span>'+esc(sh.destination)+'</span></div></div>'
    +'<div class="delivery-meta"><div><small>Départ estimé</small><b>'+fmtDate(sh.createdAt)+'</b></div><div><small>Arrivée estimée</small><b>'+fmtDate(sh.estimatedArrivalAt)+'</b></div><div><small>Transport et frais</small><b>'+fmt(sh.price+sh.extra)+' CLI</b></div></div>'
    +'<p class="market-note">Suivi de démonstration : aucun transporteur ni géolocalisation réelle n’est connecté.</p></article>';
}

/* ---------- Appareil (détection des comptes multiples) ---------- */
const Device={ key:'monempire.device',
  id(){ let d=null; try{ d=SafeStorage.getItem(this.key); }catch(e){}
    if(!d){ d='dv-'+genCode(14); try{ SafeStorage.setItem(this.key,d); }catch(e){} } return d; } };
function touchDevice(userId){ const d=Device.id();
  Store.mutate(db=>{ const u=db.users.find(x=>x.id===userId); if(!u) return;
    u.devices=u.devices||[]; if(!u.devices.includes(d)) u.devices.push(d); }); }

/* ---------- Parrainage : lien, code, filleuls, statut ---------- */
const REF_RE=/^(EMP|MNX)-[A-Z0-9]{6}$/;
const Referral={
  PKEY:'monempire.ref',
  normalize(c){ c=String(c==null?'':c).trim().toUpperCase().replace(/\s+/g,'');
    return /^[A-Z]{3}[A-Z0-9]{6}$/.test(c)?c.slice(0,3)+'-'+c.slice(3):c; },
  valid(c){ return REF_RE.test(c); },
  newCode(db){ let c; do{ c='MNX-'+genCode(6); }while(db.referrals.some(r=>r.code===c)); return c; },
  get(userId){ let r=Store.read().referrals.find(x=>x.userId===userId);
    if(!r) Store.mutate(db=>{ r={userId,code:this.newCode(db),invited:0,confirmed:0,verified:0,createdAt:new Date().toISOString()}; db.referrals.push(r); });
    this.sync(userId); return Store.read().referrals.find(x=>x.userId===userId); },
  /* Garde les compteurs de la table referrals alignés sur les relations réelles */
  sync(userId){ const db=Store.read(); const r=db.referrals.find(x=>x.userId===userId); if(!r) return;
    const rel=db.referral_relations.filter(x=>x.referrerId===userId);
    const verified=rel.filter(x=>{ const u=db.users.find(y=>y.id===x.refereeId); return u&&u.emailVerified; }).length;
    if(r.invited!==rel.length||r.confirmed!==rel.length||r.verified!==verified)
      Store.mutate(()=>{ r.invited=rel.length; r.confirmed=rel.length; r.verified=verified; }); },
  baseUrl(){ return location.href.split('#')[0].split('?')[0]; },
  linkFor(code){ return this.baseUrl()+'?ref='+encodeURIComponent(code); },
  link(userId){ return this.linkFor(this.get(userId).code); },
  findByCode(code){ code=this.normalize(code); const db=Store.read(); const r=db.referrals.find(x=>x.code===code); if(!r) return null;
    const u=db.users.find(x=>x.id===r.userId&&!x.isSeed); return u?{user:u,ref:r}:null; },

  /* Code reçu via un lien : conservé jusqu'à l'inscription */
  capture(code){ code=this.normalize(code); if(!this.valid(code)) return false;
    try{ SafeStorage.setItem(this.PKEY,JSON.stringify({code,at:new Date().toISOString()})); }catch(e){ return false; } return true; },
  pending(){ try{ const p=JSON.parse(SafeStorage.getItem(this.PKEY)); return (p&&this.valid(p.code))?p:null; }catch(e){ return null; } },
  clearPending(){ try{ SafeStorage.removeItem(this.PKEY); }catch(e){} },

  /* Association filleul → parrain. Une seule association par filleul, jamais d'auto-parrainage. */
  attach(refereeId,code,deviceId){
    code=this.normalize(code);
    const db0=Store.read(); const referee=db0.users.find(x=>x.id===refereeId);
    if(!referee||!this.valid(code)) return {ok:false,reason:'invalide'};
    if(db0.referral_relations.some(x=>x.refereeId===refereeId)) return {ok:false,reason:'deja_parraine'};
    const found=this.findByCode(code);
    if(!found){ Store.mutate(()=>{ referee.referredByCode=code; }); return {ok:false,reason:'en_attente',code}; }
    const sp=found.user;
    const digits=s=>String(s||'').replace(/\D/g,'').slice(-8);
    if(sp.id===referee.id||String(sp.email).toLowerCase()===String(referee.email).toLowerCase()||(digits(sp.phone)&&digits(sp.phone)===digits(referee.phone))){
      Store.mutate(()=>{ delete referee.referredByCode; });
      logSecurity(referee.id,'parrainage_refuse','Auto-parrainage bloqué ('+code+')');
      return {ok:false,reason:'auto_parrainage'}; }
    if(new Date(sp.createdAt)>new Date(referee.createdAt)){ Store.mutate(()=>{ delete referee.referredByCode; }); return {ok:false,reason:'ordre'}; }
    const sameDevice=!!(deviceId&&(sp.devices||[]).includes(deviceId));
    Store.mutate(db=>{ db.referral_relations.push({id:uid(),referrerId:sp.id,refereeId:referee.id,code,deviceId:deviceId||null,sameDevice,createdAt:new Date().toISOString()});
      referee.referredBy=sp.id; referee.referredByCode=code; });
    this.sync(sp.id);
    logSecurity(referee.id,'parrainage','Associé au parrain @'+sp.pseudo+' ('+code+')');
    if(sameDevice) logSecurity(referee.id,'parrainage_suspect','Même appareil que le parrain ('+code+')');
    Notif.add(sp.id,{title:'Nouveau filleul',msg:referee.prenom+' (@'+referee.pseudo+') vient de rejoindre Clicash avec ton lien.',cat:'parrainage'});
    return {ok:true,sponsor:sp};
  },
  applyPending(refereeId){ const p=this.pending(); if(!p) return null;
    const res=this.attach(refereeId,p.code,Device.id()); this.clearPending(); return res; },
  /* Rattache un code mémorisé mais introuvable lors de l'inscription, dès qu'il devient résolvable */
  reconcile(userId){ const u=Store.read().users.find(x=>x.id===userId);
    if(u&&u.referredByCode&&!u.referredBy) this.attach(userId,u.referredByCode,Device.id()); },

  /* Filleuls et statut Actif / Inactif */
  lastActivity(userId){ const db=Store.read(); const ts=[];
    db.wallet_transactions.forEach(x=>{ if(x.userId===userId&&x.type!=='parrainage') ts.push(x.date); });
    db.market_inventory.forEach(x=>{ if(x.ownerId===userId) ts.push(x.purchasedAt); });
    db.market_resales.forEach(x=>{ if(x.userId===userId) ts.push(x.createdAt); });
    db.security_logs.forEach(x=>{ if(x.userId===userId&&x.event==='connexion') ts.push(x.date); });
    return ts.length?ts.reduce((a,b)=>new Date(a)>new Date(b)?a:b):null; },
  list(referrerId){ const db=Store.read();
    return db.referral_relations.filter(x=>x.referrerId===referrerId).map(x=>{
      const u=db.users.find(y=>y.id===x.refereeId); if(!u) return null;
      const last=this.lastActivity(u.id);
      return {user:u, since:u.createdAt||x.createdAt, last, active:!!last&&(Date.now()-new Date(last))<=CONFIG.REFERRAL_ACTIVE_DAYS*864e5}; })
      .filter(Boolean).sort((a,b)=>new Date(b.since)-new Date(a.since)); },
  stats(referrerId){ const list=this.list(referrerId); const now=new Date(); const months=[];
    for(let i=5;i>=0;i--){ const d=new Date(now.getFullYear(),now.getMonth()-i,1);
      months.push({y:d.getFullYear(),m:d.getMonth(),label:d.toLocaleDateString('fr-FR',{month:'short'}).replace('.',''),count:0}); }
    list.forEach(x=>{ const d=new Date(x.since); const b=months.find(k=>k.y===d.getFullYear()&&k.m===d.getMonth()); if(b) b.count++; });
    const active=list.filter(x=>x.active).length;
    return {total:list.length,active,inactive:list.length-active,thisMonth:months[5].count,rate:list.length?Math.round(active/list.length*100):0,months,list}; },
  steps(userId){ const db=Store.read(); const u=db.users.find(x=>x.id===userId);
    return [
      {t:'Adresse e-mail vérifiée', ok:!!u.emailVerified},
      {t:'Numéro de téléphone renseigné', ok:!!u.phone},
      {t:'Photo de profil ajoutée', ok:!!u.avatar},
      {t:'Premier achat marketplace', ok:db.market_inventory.some(x=>x.ownerId===userId)} ]; }
};
const Notif={
  add(userId,n){ Store.mutate(db=>db.notifications.unshift({id:uid(),userId,title:n.title,msg:n.msg,cat:n.cat||'systeme',read:false,date:new Date().toISOString()})); },
  list(userId){ return Store.read().notifications.filter(n=>n.userId===userId); },
  unread(userId){ return this.list(userId).filter(n=>!n.read).length; },
  markRead(id){ Store.mutate(db=>{ const n=db.notifications.find(x=>x.id===id); if(n)n.read=true; }); },
  markAll(userId){ Store.mutate(db=>db.notifications.forEach(n=>{ if(n.userId===userId)n.read=true; })); }
};
/* ================= 4. UI KIT ================= */
function toast(msg,type,icon){ const t=$('#toasts'); const el=document.createElement('div');
  const icons={ok:'check-circle-2',err:'alert-triangle',warn:'alert-circle',info:'info'};
  el.className='toast t-'+(type||'info'); el.innerHTML=ic(icon||icons[type]||'info')+'<span>'+msg+'</span>';
  t.appendChild(el); lucide.createIcons();
  setTimeout(()=>{ el.classList.add('out'); setTimeout(()=>el.remove(),350); },4200); }
function openModal(o){ const root=$('#modal-root');
  root.innerHTML='<div class="modal-overlay" id="mOv"><div class="modal '+(o.wide?'modal-wide':'')+'">'
    +'<div class="modal-head"><h3>'+(o.title||'')+'</h3><button class="icon-btn" onclick="closeModal()">'+ic('x')+'</button></div>'
    +'<div class="modal-body">'+o.body+'</div>'
    +(o.actions?'<div class="modal-actions">'+o.actions+'</div>':'')+'</div></div>';
  $('#mOv').addEventListener('click',e=>{ if(e.target.id==='mOv'&&o.dismissable!==false) closeModal(); });
  window._mClose=o.onClose||null; lucide.createIcons(); if(o.onOpen) o.onOpen(); }
function closeModal(){ const root=$('#modal-root'); if(!root.innerHTML) return; root.innerHTML='';
  if(window._mClose){ const f=window._mClose; window._mClose=null; f(); } }
function emptyState(icon,t,s){ return '<div class="empty">'+ic(icon)+'<h4>'+t+'</h4><p>'+s+'</p></div>'; }
function setErr(id,msg){ const f=$('#'+id); if(!f) return; const w=f.closest('.field'); w.classList.add('err'); const e=w.querySelector('.f-err'); if(e&&msg)e.textContent=msg; }
function clearErrs(){$$('.field.err').forEach(f=>f.classList.remove('err'));}
function loadBtn(sel,on){ const b=$(sel); if(!b) return; b.classList.toggle('loading',on); b.disabled=on; }

