function parseHash(){ const h=(location.hash||'').replace(/^#\/?/,''); const parts=h.split('/'); return {page:parts[0]||'welcome', param:parts[1]}; }
function render(){ route(); }
function route(){
  if(window._cleanup){ try{window._cleanup();}catch(e){} window._cleanup=null; }
  if(window._chart){ try{window._chart.destroy();}catch(e){} window._chart=null; }
  closeModalSilent();
  const {page,param}=parseHash(); const sess=Session.current();
  if(sess&&sess.expired){ toast('Session expirée. Reconnecte-toi.','warn','clock'); }
  const logged=Session.current()&&!Session.current().expired;
  if(!logged){ if(!PUBLIC_PAGES.includes(page)){ location.hash='#/welcome'; return; } renderAuth(page); return; }
  if(PUBLIC_PAGES.includes(page)){ location.hash='#/home'; return; }
  const v=VIEWS[page]; if(!v){ location.hash='#/home'; return; }
  const u=Auth.currentUser(); if(!u){ location.hash='#/welcome'; return; }
  if(v.guard&&!v.guard(u)){ location.hash='#/home'; return; }
  $('#app').innerHTML=shellHTML(v.active,v.render(u,param),u);
  lucide.createIcons(); window.scrollTo(0,0);
  if(v.mount) v.mount(u,param);
}
function closeModalSilent(){ const r=$('#modal-root'); if(r){ r.innerHTML=''; window._mClose=null; } }
window.addEventListener('hashchange',route);

