let _captcha=''; function genCaptcha(){ _captcha=genCode(4); const el=$('#capTxt'); if(el) el.textContent=_captcha; }
let _suT=Date.now();
document.addEventListener('submit',async e=>{
  clearErrs();
  if(e.target.id==='suForm'){ e.preventDefault();
    if($('#su-hp').value){ toast('Inscription bloquée.','err','shield'); return; }
    if(Date.now()-_suT<3000){ toast('Formulaire soumis trop rapidement. Vérifie les champs.','warn','clock'); return; }
    const d={nom:$('#su-nom').value.trim(),prenom:$('#su-prenom').value.trim(),pseudo:$('#su-pseudo').value.trim(),
      email:$('#su-email').value.trim(),phone:$('#su-phone').value.trim(),password:$('#su-pass').value};
    let ok=true;
    if(d.nom.length<2){setErr('su-nom','Nom trop court.');ok=false;}
    if(d.prenom.length<2){setErr('su-prenom','Prénom trop court.');ok=false;}
    if(!/^[a-zA-Z0-9_]{3,20}$/.test(d.pseudo)){setErr('su-pseudo','3 à 20 lettres, chiffres ou tirets bas.');ok=false;}
    if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(d.email)){setErr('su-email','Adresse e-mail invalide.');ok=false;}
    if(!/^\+?[0-9 ]{8,15}$/.test(d.phone)){setErr('su-phone','Numéro invalide (ex. +228 90 00 00 00).');ok=false;}
    if(d.password.length<8||!/[a-zA-Z]/.test(d.password)||!/[0-9]/.test(d.password)){setErr('su-pass','8 caractères min., lettres et chiffres.');ok=false;}
    if($('#su-pass2').value!==d.password){setErr('su-pass2','Les mots de passe ne correspondent pas.');ok=false;}
    if($('#su-code').value.trim().toUpperCase()!==_captcha){setErr('su-code','Code de sécurité incorrect.');ok=false;}
    if(!$('#su-cgu').checked){setErr('su-cgu','Tu dois accepter les conditions.');ok=false;}
    if(!ok) return;
    loadBtn('#suBtn',true);
    try{ await Auth.signup(d); toast('Compte créé avec succès','ok','check-circle-2'); signupReferralToast(); location.hash='#/home'; openVerifyModal(true); }
    catch(err){ toast(err.message,'err','alert-triangle'); }
    loadBtn('#suBtn',false);
  }
  if(e.target.id==='liForm'){ e.preventDefault();
    const id=$('#li-id').value.trim(), p=$('#li-pass').value; let ok=true;
    if(!id){setErr('li-id','Identifiant requis.');ok=false;} if(!p){setErr('li-pass','Mot de passe requis.');ok=false;}
    if(!ok) return; loadBtn('#liBtn',true);
    try{ const u=await Auth.login(id,p); toast('Ravi de te revoir, '+u.prenom+' !','ok','sparkles'); location.hash='#/home'; }
    catch(err){ toast(err.message,'err','alert-triangle'); }
    loadBtn('#liBtn',false);
  }
  if(e.target.id==='fgForm'){ e.preventDefault();
    const em=$('#fg-email').value.trim();
    if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(em)){ setErr('fg-email','Adresse e-mail invalide.'); return; }
    try{ const r=Auth.findForReset(em); openResetModal(r.userId,r.code,em); }
    catch(err){ setErr('fg-email',err.message); }
  }
});
function openResetModal(userId,code,email){ openModal({title:'Code de réinitialisation',
  body:'<p style="font-size:13.5px;color:#4B5563;margin-bottom:10px">Un code a été envoyé à <b>'+esc(email)+'</b>.</p>'
  +'<div class="info-strip" style="margin-bottom:14px">'+ic('info')+'<span>Mode démonstration locale : avec Supabase Auth, ce code serait envoyé par e-mail. Code : <b>'+code+'</b></span></div>'
  +'<form id="rsForm" novalidate><div class="field"><label>Code reçu</label><input class="input" id="rs-code" placeholder="6 caractères"><div class="f-err"></div></div>'
  +'<div class="field"><label>Nouveau mot de passe</label><input class="input" id="rs-p1" type="password" placeholder="8 caractères min."><div class="f-err"></div></div>'
  +'<div class="field"><label>Confirmation</label><input class="input" id="rs-p2" type="password" placeholder="Répète le mot de passe"><div class="f-err"></div></div></form>',
  actions:'<button class="btn btn-outline" onclick="closeModal()">Annuler</button><button class="btn btn-primary" id="rsBtn" onclick="doReset(\''+userId+'\')">'+ic('check')+'Réinitialiser</button>'}); }
async function doReset(userId){ clearErrs(); const c=$('#rs-code').value.trim().toUpperCase(), p1=$('#rs-p1').value, p2=$('#rs-p2').value; let ok=true;
  if(c.length!==6){setErr('rs-code','Code invalide.');ok=false;}
  if(p1.length<8||!/[a-zA-Z]/.test(p1)||!/[0-9]/.test(p1)){setErr('rs-p1','8 caractères min., lettres et chiffres.');ok=false;}
  if(p1!==p2){setErr('rs-p2','Ne correspond pas.');ok=false;}
  if(!ok) return; loadBtn('#rsBtn',true);
  try{ await Auth.resetPassword(userId,c,p1); closeModal(); toast('Mot de passe réinitialisé. Connecte-toi.','ok','check-circle-2'); go('login'); }
  catch(err){ toast(err.message,'err','alert-triangle'); } loadBtn('#rsBtn',false); }
function openVerifyModal(first){ const u=Auth.currentUser(); if(!u||u.emailVerified) return;
  const code=Auth.requestCode(u.id);
  openModal({title:'Vérifie ton adresse e-mail',
    body:'<p style="font-size:13.5px;color:#4B5563;margin-bottom:10px">Un code de vérification a été envoyé à <b>'+esc(u.email)+'</b>.</p>'
    +'<div class="info-strip" style="margin-bottom:14px">'+ic('info')+'<span>Mode démonstration locale : avec Supabase Auth, l\u2019e-mail serait envoyé automatiquement. Code : <b>'+code+'</b></span></div>'
    +'<div class="field"><label>Code de vérification</label><input class="input" id="vf-code" placeholder="6 caractères" maxlength="6"><div class="f-err"></div></div>',
    actions:'<button class="btn btn-ghost" onclick="openVerifyModal(true)">'+ic('refresh-cw')+'Renvoyer</button><button class="btn btn-primary" onclick="doVerify()">'+ic('badge-check')+'Vérifier</button>'}); }
function doVerify(){ clearErrs(); const u=Auth.currentUser(); const c=$('#vf-code').value.trim().toUpperCase();
  if(c.length!==6){ setErr('vf-code','Code invalide.'); return; }
  if(Auth.verifyEmail(u.id,c)){ closeModal(); toast('Adresse e-mail vérifiée','ok','badge-check'); Notif.add(u.id,{title:'E-mail vérifié',msg:'Ton adresse e-mail est confirmée. Objectif de parrainage mis à jour.',cat:'securite'}); render(); }
  else setErr('vf-code','Code incorrect ou expiré.'); }
function signupReferralToast(){ const r=Auth.lastReferral; Auth.lastReferral=null; if(!r) return;
  if(r.ok) setTimeout(()=>toast('Parrainé par <b>'+esc(r.sponsor.prenom)+'</b> (@'+esc(r.sponsor.pseudo)+')','ok','users'),700);
  else if(r.reason==='auto_parrainage') setTimeout(()=>toast('Parrainage non appliqué : tu ne peux pas te parrainer toi-même.','warn','shield'),700); }
function doLogout(){ Auth.logout(); toast('Déconnexion réussie','info','log-out'); location.hash='#/welcome'; }

