function marketTrendHTML(p){
  const t=Market.trend(p);
  return '<span class="badge '+t.className+'">'+ic(t.icon)+t.name+' <span>'+marketFormatDelta(p)+'</span></span>';
}
function marketProductCard(p){
  const value=Market.quote(p);
  return '<article class="card product-card card-hover"><div class="product-image"><img src="'+esc(p.image)+'" alt="'+esc(p.name)+'" loading="lazy"><span class="badge b-white">'+esc(p.category)+'</span></div>'
    +'<div class="product-card-body"><div class="product-id">'+esc(p.id)+'</div><h3>'+esc(p.name)+'</h3><p>'+esc(p.description)+'</p>'
    +'<div class="product-price-row"><div><small>Prix d’achat</small><b>'+fmt(p.price)+' CLI</b><small>Valeur estimée · '+fmt(value)+' CLI</small></div>'+marketTrendHTML(p)+'</div>'
    +'<div class="product-mini-chart">'+marketChart(Market.history(p,12),false)+'<span>14 jours · estimation simulée</span></div>'
    +'<div class="product-card-foot"><span>'+ic('package')+fmt(p.stock)+' disponibles</span><button class="btn btn-primary btn-sm" onclick="go(\'product/'+encodeURIComponent(p.id)+'\')">Voir le produit</button></div></div></article>';
}
function inventorySummary(userId){
  const items=Market.inventory(userId);
  return {items,value:items.reduce((sum,x)=>sum+Market.currentValue(x),0),pending:Market.resales(userId).filter(x=>x.status==='En attente de traitement').length,shipments:Market.shipments(userId).filter(x=>x.status!=='Réception confirmée').length};
}
