    +'<div class="market-filters" id="marketCatalog"><label class="market-search">'+ic('search')+'<input id="marketSearch" class="input" type="search" placeholder="Rechercher un produit ou une catégorie" autocomplete="off"></label>'
    +'<div class="chips market-category-chips" id="marketCategories"><button class="chip active" data-cat="all">Toutes les catégories</button>'+MARKET_CATEGORIES.map(c=>'<button class="chip" data-cat="'+esc(c)+'">'+esc(c)+'</button>').join('')+'</div></div>'
