function savePref(k,v){ const u=Auth.currentUser(); Store.mutate(db=>{ let s=db.user_settings.find(x=>x.userId===u.id); if(!s){ s={userId:u.id}; db.user_settings.push(s);} s[k]=v; }); toast('Préférence enregistrée','ok','check'); }
function saveDisplay(reduit){ savePref('display',reduit?'reduit':'confort'); document.documentElement.classList.toggle('reduce-motion',reduit); }
function openProfileEdit(){ const u=Auth.currentUser();
  openModal({title:'Modifier mes informations',wide:true,
    body:'<div style="display:flex;gap:14px;align-items:center;margin-bottom:16px">'+avatarHTML(u,'lg')
    +'<div><label class="btn btn-ghost btn-sm" style="cursor:pointer">'+ic('camera')+'Changer la photo<input type="file" id="pf-avatar" accept="image/*" style="display:none"></label>'
    +'<div style="font-size:11.5px;color:var(--gray);margin-top:5px">Image uniquement, 1,5 Mo max.</div></div></div>'
    +'<form id="pfForm" novalidate><div class="f-row"><div class="field"><label>Nom</label><input class="input" id="pf-nom" value="'+esc(u.nom)+'"><div class="f-err"></div></div>'
    +'<div class="field"><label>Prénom</label><input class="input" id="pf-prenom" value="'+esc(u.prenom)+'"><div class="f-err"></div></div></div>'
    +'<div class="field"><label>Pseudo</label><input class="input" id="pf-pseudo" value="'+esc(u.pseudo)+'"><div class="f-err"></div></div>'
    +'<div class="f-row"><div class="field"><label>Téléphone</label><input class="input" id="pf-phone" value="'+esc(u.phone)+'"><div class="f-err"></div></div>'
    +'<div class="field"><label>E-mail</label><input class="input" id="pf-email" value="'+esc(u.email)+'"><div class="f-err"></div></div></div></form>',
    actions:'<button class="btn btn-outline" onclick="closeModal()">Annuler</button><button class="btn btn-primary" id="pfBtn" onclick="saveProfile()">Enregistrer</button>',
    onOpen(){ $('#pf-avatar').addEventListener('change',e=>{ const f=e.target.files[0]; if(!f) return;
      if(!f.type.startsWith('image/')){ toast('Fichier non autorisé : image uniquement.','err','image'); return; }
      if(f.size>1572864){ toast('Image trop lourde (1,5 Mo max).','err','image'); return; }
      const rd=new FileReader(); rd.onload=()=>Store.mutate(db=>{ db.users.find(x=>x.id===u.id).avatar=rd.result; toast('Photo mise à jour','ok','camera'); closeModal(); openProfileEdit(); });
      rd.readAsDataURL(f); }); } }); }
function saveProfile(){ clearErrs(); const u=Auth.currentUser(); const db=Store.read();
  const d={nom:$('#pf-nom').value.trim(),prenom:$('#pf-prenom').value.trim(),pseudo:$('#pf-pseudo').value.trim(),phone:$('#pf-phone').value.trim(),email:$('#pf-email').value.trim()}; let ok=true;
  if(d.nom.length<2){setErr('pf-nom','Nom trop court.');ok=false;}
  if(d.prenom.length<2){setErr('pf-prenom','Prénom trop court.');ok=false;}
  if(!/^[a-zA-Z0-9_]{3,20}$/.test(d.pseudo)){setErr('pf-pseudo','3 à 20 lettres, chiffres ou tirets bas.');ok=false;}
  else if(db.users.some(x=>x.id!==u.id&&!x.isSeed&&x.pseudo.toLowerCase()===d.pseudo.toLowerCase())){setErr('pf-pseudo','Ce pseudo est déjà pris.');ok=false;}
  if(!/^\+?[0-9 ]{8,15}$/.test(d.phone)){setErr('pf-phone','Numéro invalide.');ok=false;}
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(d.email)){setErr('pf-email','E-mail invalide.');ok=false;}
  else if(db.users.some(x=>x.id!==u.id&&!x.isSeed&&x.email.toLowerCase()===d.email.toLowerCase())){setErr('pf-email','Cet e-mail est déjà utilisé.');ok=false;}
  if(!ok) return;
  const oldEmail=db.users.find(x=>x.id===u.id).email;
  Store.mutate(db2=>{ const uu=db2.users.find(x=>x.id===u.id); Object.assign(uu,d); if(d.email!==oldEmail) uu.emailVerified=false; });
  if(d.email!==oldEmail) Notif.add(u.id,{title:'E-mail modifié',msg:'Ton adresse e-mail a changé. Une nouvelle vérification est requise.',cat:'securite'});
  closeModal(); toast('Profil mis à jour','ok','check-circle-2'); render(); }
async function changePwd(){ clearErrs(); const o=$('#pw-old').value,a=$('#pw-1').value,b=$('#pw-2').value; let ok=true;
  if(!o){setErr('pw-old','Requis.');ok=false;}
  if(a.length<8||!/[a-zA-Z]/.test(a)||!/[0-9]/.test(a)){setErr('pw-1','8 caractères min., lettres et chiffres.');ok=false;}
  if(a!==b){setErr('pw-2','Ne correspond pas.');ok=false;}
  if(!ok) return; loadBtn('#pwBtn',true);
  try{ await Auth.changePassword(Auth.currentUser().id,o,a); toast('Mot de passe modifié','ok','lock');
    Notif.add(Auth.currentUser().id,{title:'Mot de passe modifié',msg:'Le mot de passe de ton compte a été mis à jour.',cat:'securite'});
    $('#pw-old').value='';$('#pw-1').value='';$('#pw-2').value=''; }
  catch(err){ toast(err.message,'err','alert-triangle'); }
  loadBtn('#pwBtn',false); }
function openLegal(kind){ const C={
  cgu:{t:'Conditions d’utilisation',b:'<div style="font-size:13.5px;color:#4B5563;line-height:1.9"><p><b>1. Objet.</b> Clicash présente une marketplace électronique, un portefeuille de crédits internes CLI et des estimations de marché.</p><p><b>2. CLI.</b> Les CLI sont des crédits internes. Le taux de référence est de 1 000 CLI pour 1 000 F CFA après confirmation par un prestataire de paiement connecté.</p><p><b>3. Estimations.</b> Les variations de valeur, prix de revente et délais de livraison sont indicatifs. Aucune hausse, vente ou livraison n’est garantie.</p><p><b>4. Version actuelle.</b> Les données sont enregistrées localement sur cet appareil. Aucun paiement, acheteur, fournisseur ou transporteur réel n’est connecté.</p></div>'},
  priv:{t:'Politique de confidentialité',b:'<div style="font-size:13.5px;color:#4B5563;line-height:1.9"><p><b>Données collectées :</b> identité, coordonnées, données de portefeuille, d’inventaire et de commande, historique de portefeuille.</p><p><b>Finalités :</b> fonctionnement du service, sécurité, lutte contre la fraude, amélioration de l\u2019expérience.</p><p><b>Protection :</b> mots de passe hachés, accès contrôlés par utilisateur (Row Level Security), journalisation des opérations sensibles, aucune exposition de clés secrètes côté client.</p><p><b>Droits :</b> tu peux demander l\u2019accès, la rectification ou la suppression de tes données via le centre d\u2019assistance.</p></div>'},
  faq:{t:'Questions fréquentes',b:'<details class="faq"><summary>Que sont les CLI ?</summary><div class="a">Ce sont des crédits internes. 1 000 F CFA correspondent à 1 000 CLI après confirmation du paiement par un prestataire réellement connecté. Cette version ne connecte aucun prestataire.</div></details>'
    +'<details class="faq"><summary>Les prix et reventes sont-ils garantis ?</summary><div class="a">Non. Les prix, valeurs de revente, frais et délais sont estimatifs. Une demande de revente ne garantit ni acheteur ni crédit de CLI.</div></details>'
    +'<details class="faq"><summary>Comment fonctionne le parrainage ?</summary><div class="a">Tu partages ton lien personnel. Les récompenses ne sont attribuées qu\u2019après inscription réelle, confirmation et vérification du compte de ton filleul — jamais sur un simple clic.</div></details>'
    +'<details class="faq"><summary>Comment retirer mes gains ?</summary><div class="a">Depuis la page « Retrait » : règle une seule fois les frais de déblocage ('+fcfa(WD.cfg().unlockFee)+'), valide tes objectifs, puis fais ta demande. Minimum '+fcfa(WD.cfg().minFirst)+' pour le premier retrait, '+fcfa(WD.cfg().minNext)+' ensuite. Chaque demande est vérifiée avant paiement.</div></details>'
    },
  about:{t:'À propos de Clicash',b:'<div style="text-align:center;margin-bottom:14px"><div class="tb-logo floaty" style="width:56px;height:56px;border-radius:18px;margin:0 auto">'+logoImg()+'</div><h3 style="margin-top:10px">Clicash</h3><p style="color:var(--gray);font-size:13px">Version client 1.0 · 2026</p></div>'
    +'<div style="font-size:13.5px;color:#4B5563;line-height:1.9"><p>Clicash est une marketplace électronique pensée pour l\u2019Afrique francophone, avec une première orientation vers le Togo. Les estimations de prix sont indicatives et la version actuelle fonctionne localement sur cet appareil.</p><p style="margin-top:8px"><b>Référence :</b> 1 Cli = 1 FCFA (équivalence indicative). Les récompenses convertibles et paiements réels seront activés après vérification des exigences légales, des opérateurs et des conditions d\u2019âge applicables.</p></div>'} };
  const c=C[kind]; openModal({title:c.t,wide:kind==='faq'||kind==='cgu'||kind==='priv',body:c.b,actions:'<button class="btn btn-primary" onclick="closeModal()">Fermer</button>'}); }
function openHelp(){ openModal({title:'Centre d\u2019assistance',
  body:'<p style="font-size:13px;color:var(--gray);margin-bottom:14px">Décris ton problème : notre équipe te répondra. Tu peux aussi consulter la FAQ.</p>'
  +'<form id="spForm" novalidate><div class="field"><label>Sujet</label><input class="input" id="sp-subj" placeholder="Ex. Question sur mes Cli"><div class="f-err"></div></div>'
  +'<div class="field"><label>Message</label><textarea class="input" id="sp-msg" placeholder="Décris ta demande…"></textarea><div class="f-err"></div></div></form>',
  actions:'<button class="btn btn-outline" onclick="closeModal();openLegal(\'faq\')">'+ic('help-circle')+'FAQ</button><button class="btn btn-primary" onclick="sendSupport()">'+ic('send')+'Envoyer</button>'}); }
function sendSupport(){ clearErrs(); const s=$('#sp-subj').value.trim(),m=$('#sp-msg').value.trim(); let ok=true;
  if(s.length<4){setErr('sp-subj','Sujet trop court.');ok=false;}
  if(m.length<10){setErr('sp-msg','Message trop court (10 caractères min.).');ok=false;}
  if(!ok) return; const u=Auth.currentUser();
  Store.mutate(db=>db.support_requests.unshift({id:uid(),userId:u.id,subject:s,message:m,status:'ouvert',date:new Date().toISOString()}));
  Notif.add(u.id,{title:'Demande d\u2019assistance envoyée',msg:'Ta demande « '+s+' » a bien été enregistrée.',cat:'systeme'});
  closeModal(); toast('Demande envoyée. Nous reviendrons vers toi.','ok','send'); }

